const CLEAN = Symbol('clean');

function pruneDirtyFields(node: any): any {
  if (node === true) {
    return true;
  }

  if (Array.isArray(node)) {
    let hasDirty = false;
    const result = node.map((item) => {
      const pruned = pruneDirtyFields(item);

      if (pruned === CLEAN) {
        return undefined;
      }

      hasDirty = true;
      return pruned;
    });

    return hasDirty ? result : CLEAN;
  }

  if (isObject(node)) {
    let hasDirty = false;
    const result: Record<string, any> = {};

    for (const key in node) {
      const pruned = pruneDirtyFields(node[key]);

      if (pruned !== CLEAN) {
        result[key] = pruned;
